insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('landshop-allocation-documents','landshop-allocation-documents',false,31457280,array['application/pdf','image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy allocation_documents_upload on storage.objects for insert to authenticated with check(bucket_id='landshop-allocation-documents' and (storage.foldername(name))[1]=auth.uid()::text and public.landshop_is_management(auth.uid()) and exists(select 1 from public.allocation_sites s where s.id::text=(storage.foldername(name))[2]));
create policy allocation_documents_read on storage.objects for select to authenticated using(bucket_id='landshop-allocation-documents' and (public.landshop_is_management(auth.uid()) or exists(select 1 from public.allocation_cases c where c.site_id::text=(storage.foldername(name))[2] and c.applicant_id=auth.uid())));
create policy allocation_client_site_read on public.allocation_sites for select to authenticated using(exists(select 1 from public.allocation_cases c where c.site_id=allocation_sites.id and c.applicant_id=auth.uid()));
